<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
if(file_exists(dirname(__DIR__).'/.env')) Dotenv\Dotenv::createImmutable(dirname(__DIR__))->safeLoad();
use Firebase\JWT\JWT; use Firebase\JWT\Key;
header('Content-Type: application/json'); header('Access-Control-Allow-Origin: '.($_ENV['CORS_ORIGIN']??'http://localhost:5173')); header('Access-Control-Allow-Headers: Content-Type, Authorization, X-Drone-Api-Key'); header('Access-Control-Allow-Methods: GET,POST,PUT,PATCH,DELETE,OPTIONS'); header('X-Content-Type-Options: nosniff');
if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(204);exit;}
function res($v,int $s=200):never{http_response_code($s);echo json_encode($v);exit;} function err($c,$m,$s):never{res(['error'=>['code'=>$c,'message'=>$m]],$s);}
function db():PDO{static $p;if(!$p)$p=new PDO('mysql:host='.($_ENV['DB_HOST']??'127.0.0.1').';port='.($_ENV['DB_PORT']??3306).';dbname='.($_ENV['DB_NAME']??'skyfleet').';charset=utf8mb4',$_ENV['DB_USER']??'',$_ENV['DB_PASS']??'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);return $p;}
function body():array{$v=json_decode(file_get_contents('php://input'),true);if(!is_array($v))err('invalid_json','Expected JSON body',400);return $v;}
function auth():array{$h=$_SERVER['HTTP_AUTHORIZATION']??$_SERVER['REDIRECT_HTTP_AUTHORIZATION']??'';if(!$h&&function_exists('getallheaders')){$headers=getallheaders();$h=$headers['Authorization']??$headers['authorization']??'';}if(!preg_match('/^Bearer\s+(.+)$/i',$h,$m))err('unauthorized','Sign in required',401);try{return (array)JWT::decode($m[1],new Key($_ENV['JWT_SECRET']??'','HS256'))->sub;}catch(Throwable){err('unauthorized','Invalid or expired token',401);}}
function admin():array{$u=auth();if($u['role']!=='admin')err('forbidden','Admin access required',403);return $u;}
function alert(int $id,string $type,string $msg):void{$q=db()->prepare("SELECT id FROM alerts WHERE drone_id=? AND type=? AND status='open'");$q->execute([$id,$type]);if(!$q->fetch()){$q=db()->prepare('INSERT INTO alerts(drone_id,type,message) VALUES(?,?,?)');$q->execute([$id,$type,$msg]);}}
function distance(float $a,float $b,float $c,float $d):float{$r=6371000;$p=deg2rad($a);$q=deg2rad($c);$x=deg2rad($c-$a);$y=deg2rad($d-$b);$h=sin($x/2)**2+cos($p)*cos($q)*sin($y/2)**2;return 2*$r*atan2(sqrt($h),sqrt(1-$h));}
try{$m=$_SERVER['REQUEST_METHOD'];$path=rtrim(preg_replace('#^/api/v1#','',parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)),'/')?:'/';
if($m==='GET'&&$path==='/health')res(['ok'=>true]);
if($m==='POST'&&$path==='/auth/login'){$b=body();$q=db()->prepare('SELECT id,name,email,password_hash,role FROM users WHERE email=?');$q->execute([strtolower(trim($b['email']??''))]);$u=$q->fetch();if(!$u||!password_verify($b['password']??'',$u['password_hash']))err('invalid_credentials','Email or password incorrect',401);$now=time();$user=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];$token=JWT::encode(['iat'=>$now,'exp'=>$now+3600,'sub'=>$user],$_ENV['JWT_SECRET']??'','HS256');res(['token'=>$token,'user'=>$user]);}
if($m==='POST'&&$path==='/telemetry'){$b=body();$q=db()->prepare('SELECT id FROM drones WHERE api_key_hash=?');$q->execute([hash('sha256',$_SERVER['HTTP_X_DRONE_API_KEY']??'')]);$d=$q->fetch();if(!$d)err('invalid_api_key','Invalid drone API key',401);$battery=filter_var($b['battery_pct']??null,FILTER_VALIDATE_INT);$lat=filter_var($b['latitude']??null,FILTER_VALIDATE_FLOAT);$lng=filter_var($b['longitude']??null,FILTER_VALIDATE_FLOAT);$alt=filter_var($b['altitude_m']??null,FILTER_VALIDATE_FLOAT);if($battery===false||$battery<0||$battery>100||$lat===false||$lat < -90||$lat>90||$lng===false||$lng < -180||$lng>180||$alt===false)err('validation_error','Invalid telemetry fields',422);$id=(int)$d['id'];$q=db()->prepare('INSERT INTO telemetry(drone_id,battery_pct,latitude,longitude,altitude_m,speed_ms,recorded_at) VALUES(?,?,?,?,?,?,?)');$q->execute([$id,$battery,$lat,$lng,$alt,(float)($b['speed_ms']??0),$b['recorded_at']??date('Y-m-d H:i:s')]);db()->prepare("UPDATE drones SET status='active',last_seen_at=NOW() WHERE id=?")->execute([$id]);if($battery<=20)alert($id,'low_battery',"Battery at {$battery}%");foreach(db()->query('SELECT * FROM geofences WHERE active=1') as $g)if(distance($lat,$lng,$g['center_lat'],$g['center_lng'])>$g['radius_m'])alert($id,'geofence_breach','Outside geofence: '.$g['name']);res(['ok'=>true],201);}
$u=auth();if($m==='GET'&&$path==='/auth/me')res(['user'=>$u]);
if($m==='GET'&&$path==='/drones'){$sql="SELECT d.*,t.battery_pct,t.latitude,t.longitude,t.altitude_m,t.speed_ms,t.recorded_at FROM drones d LEFT JOIN telemetry t ON t.id=(SELECT id FROM telemetry WHERE drone_id=d.id ORDER BY recorded_at DESC,id DESC LIMIT 1)";if($u['role']!=='admin')$sql.=' WHERE EXISTS(SELECT 1 FROM assignments a WHERE a.drone_id=d.id AND a.pilot_id='.(int)$u['id'].' AND a.unassigned_at IS NULL)';res(db()->query($sql)->fetchAll());}
if($m==='POST'&&$path==='/drones'){admin();$b=body();if(empty($b['name'])||empty($b['serial_no']))err('validation_error','name and serial_no are required',422);$key=bin2hex(random_bytes(24));$q=db()->prepare('INSERT INTO drones(serial_no,name,model,api_key_hash) VALUES(?,?,?,?)');$q->execute([$b['serial_no'],$b['name'],$b['model']??null,hash('sha256',$key)]);res(['id'=>(int)db()->lastInsertId(),'api_key'=>$key],201);}
if(preg_match('#^/drones/(\d+)/telemetry$#',$path,$x)&&$m==='GET'){$id=(int)$x[1];if($u['role']!=='admin'){$q=db()->prepare('SELECT id FROM assignments WHERE drone_id=? AND pilot_id=? AND unassigned_at IS NULL');$q->execute([$id,$u['id']]);if(!$q->fetch())err('not_found','Drone not found',404);}$limit=min(1000,max(1,(int)($_GET['limit']??100)));$q=db()->prepare("SELECT * FROM telemetry WHERE drone_id=? ORDER BY recorded_at DESC LIMIT {$limit}");$q->execute([$id]);res(array_reverse($q->fetchAll()));}
if($m==='GET'&&$path==='/alerts'){$s=$_GET['status']??'open';$sql='SELECT a.*,d.name drone_name FROM alerts a JOIN drones d ON d.id=a.drone_id WHERE a.status=?';$args=[$s];if($u['role']!=='admin'){$sql.=' AND EXISTS(SELECT 1 FROM assignments x WHERE x.drone_id=d.id AND x.pilot_id=? AND x.unassigned_at IS NULL)';$args[]=$u['id'];}$q=db()->prepare($sql.' ORDER BY a.created_at DESC');$q->execute($args);res($q->fetchAll());}
if(preg_match('#^/alerts/(\d+)$#',$path,$x)&&$m==='PATCH'){$b=body();if(!in_array($b['status']??'', ['acknowledged','resolved'],true))err('validation_error','Invalid alert status',422);$q=db()->prepare('UPDATE alerts SET status=? WHERE id=?');$q->execute([$b['status'],$x[1]]);res(['ok'=>true]);}
if($path==='/pilots'&&$m==='GET'){admin();res(db()->query("SELECT id,name,email FROM users WHERE role='pilot'")->fetchAll());}
if($path==='/pilots'&&$m==='POST'){admin();$b=body();if(!filter_var($b['email']??'',FILTER_VALIDATE_EMAIL)||strlen($b['password']??'')<10)err('validation_error','Valid email and 10-character password required',422);$q=db()->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'pilot')");$q->execute([$b['name'],$b['email'],password_hash($b['password'],PASSWORD_DEFAULT)]);res(['id'=>(int)db()->lastInsertId()],201);}
if($path==='/assignments'&&$m==='POST'){admin();$b=body();$q=db()->prepare('INSERT INTO assignments(drone_id,pilot_id) VALUES(?,?)');$q->execute([(int)$b['drone_id'],(int)$b['pilot_id']]);res(['id'=>(int)db()->lastInsertId()],201);}
if($path==='/geofences'&&$m==='GET'){admin();res(db()->query('SELECT * FROM geofences')->fetchAll());}if($path==='/geofences'&&$m==='POST'){admin();$b=body();$q=db()->prepare('INSERT INTO geofences(name,center_lat,center_lng,radius_m,active) VALUES(?,?,?,?,?)');$q->execute([$b['name'],$b['center_lat'],$b['center_lng'],$b['radius_m'],(int)($b['active']??1)]);res(['id'=>(int)db()->lastInsertId()],201);}
err('not_found','Endpoint not found',404);
}catch(PDOException $e){error_log($e->getMessage());err('database_error','Database operation failed',500);}catch(Throwable $e){error_log($e->getMessage());err('server_error','Unexpected server error',500);}
